<script lang="ts">
	import { page } from "$app/state";
	import { Constants } from "$lib";
	import * as Empty from "$lib/components/ui/empty";
	import { onDestroy } from "svelte";
	import { signerIdentity } from "$localLibrary/publication";
	import ErrorComponent from "./ErrorComponent.svelte";
	import Grid from "./ui/Grid.svelte";
	import { buttonVariants } from "./ui/button";
	import Spinner from "./ui/spinner/spinner.svelte";

	let {
		feed = $bindable(),
		onSearch
	}: {
		feed: UserFeedResponse | undefined;
		onSearch: () => Promise<void>;
	} = $props();

	let isMounted = $state(false);
	let error = $state<Constants.Error.Error>();

	let directoryEpoch = 0, directoryDisposed = false;
	onDestroy(() => { directoryDisposed = true; directoryEpoch++; });
	$effect(() => {
		const owner = $signerIdentity.owner, generation = $signerIdentity.generation;
		const revision = ++directoryEpoch;
		feed = undefined; error = undefined; isMounted = false;
		if (!owner) {
			error = new Constants.Error.Error("Connect your public identity", "This instance's user directory requires a connected identity bound to an account. Manage your public identity in Settings, then search again.");
			isMounted = true; return;
		}
		void (async () => {
			try { await onSearch(); }
			catch (cause) {
				if (directoryDisposed || revision !== directoryEpoch) return;
				error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown;
			}
			if (!directoryDisposed && revision === directoryEpoch) isMounted = true;
		})();
	});
</script>

{#if error}
	<ErrorComponent {error} />
{:else if isMounted && feed}
	<Grid class="gap-1" breakpoints={{ 0: 4, 1368: 3, 768: 2, 525: 1 }}>
		{#each feed.data as user}
			<article>
				<a
					class={buttonVariants({
						class: "w-full justify-start border-none",
						variant: "outline"
					})}
					href="/user/{user.id}"
					title={user.name}
				>
					<span class="truncate">
						{user.name}
					</span>
				</a>
			</article>
		{/each}
	</Grid>
{:else}
	<Empty.Root>
		<Spinner class="size-10" />
	</Empty.Root>
{/if}
